import csvfrom datetime import datetimedef tekst_til_tall(tekst):    if tekst == "-" or tekst == "":        return None    tekst = tekst.replace(",", ".")    return float(tekst)def skifore_dager(data, aar):    antall = 0    for dag in data:        dato = dag[0]        snodybde = dag[1]        i_sesong = (dato.year == aar - 1 and dato.month >= 11) or (dato.year == aar and dato.month <= 5)        if i_sesong and snodybde is not None and snodybde >= 20:            antall = antall + 1    return antalldata = []with open("sinnes_2014_2025_med_makstemperatur.csv", encoding="utf-8-sig") as fil:    leser = csv.reader(fil, delimiter=";")    next(leser)    for linje in leser:        if linje[2] == "":            continue        dato = datetime.strptime(linje[2], "%d.%m.%Y")        snodybde = tekst_til_tall(linje[7])        data.append((dato, snodybde))aar = int(input("Skriv  inn årstall:"))antall = skifore_dager(data, aar)print(f"Det var {antall} dager med skiføre i sesongen {aar}.")